def can_win(N, M, S):
    # Check if the starting or ending square is a Game Over Square
    if S[0] == 1 or S[N] == 1:
        return -1

    # Initialize the graph
    graph = [[] for _ in range(N + 1)]
    for i in range(N):
        if S[i] == 0:
            for j in range(1, M + 1):
                if i + j <= N:
                    graph[i].append((i + j, j))

    # Priority queue for BFS
    pq = [(0, 0, [])]  # (turns, current_square, sequence)

    while pq:
        turns, current_square, sequence = heapq.heappop(pq)

        # If we reach the goal square, return the sequence
        if current_square == N:
            return sequence

        # Explore all possible moves from the current square
        for next_square, move in graph[current_square]:
            if next_square not in sequence:
                heapq.heappush(pq, (turns + 1, next_square, sequence + [move]))

    # If no valid sequence is found, return -1
    return -1

