def find_min_sequence(N, M, S):
    # Convert the string S to a list of integers
    S = list(map(int, S))

    # Initialize the queue for BFS
    queue = deque([(0, [], 0)])  # (current_position, sequence_of_spins, turns_taken)

    # Set to keep track of visited positions to avoid cycles
    visited = set()

    while queue:
        current_position, sequence, turns = queue.popleft()

        # If we have reached Square N, return the sequence
        if current_position == N:
            return ' '.join(map(str, sequence))

        # If we have already visited this position, skip it
        if (current_position, turns) in visited:
            continue

        # Mark the current position as visited
        visited.add((current_position, turns))

        # Try all possible spins
        for spin in range(1, M + 1):
            new_position = current_position + spin

            # If the new position is within bounds and not a Game Over Square, add it to the queue
            if 0 <= new_position <= N and S[new_position] == 0:
                queue.append((new_position, sequence + [spin], turns + 1))

    # If no valid sequence is found, return -1
    return -1

