import heapq

def bfs(graph, start, end):
    queue = [(0, start, [])]  # (distance, current_square, path)
    visited = set()

    while queue:
        dist, current, path = heapq.heappop(queue)

        if current == end:
            return path + [current]

        if current in visited:
            continue

        visited.add(current)

        for neighbor, cost in graph[current].items():
            if neighbor not in visited:
                heapq.heappush(queue, (dist + cost, neighbor, path + [current]))

    return None

