def count_permutations(n, k):
    MOD = 10**9 + 7

    # Base cases
    if n == 1:
        if k == 0:
            return 1
        else:
            return 0

    # If k is not equal to n(n-1)/2, no permutation can have the desired oddness
    if k != n * (n - 1) // 2:
        return 0

    # Initialize the DP table
    dp = [0] * (n + 1)
    dp[0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[j] = (dp[j] + dp[j - i]) % MOD

    return dp[n]

