def count_permutations(n, k):
    MOD = 10**9 + 7

    # Base case: dp[0][0] = 1 (only the identity permutation)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(k + 1):
            # Add the element i to the permutation of {1, 2, ..., i-1}
            for x in range(1, i + 1):
                if j >= abs(x - i):
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - abs(x - i)]) % MOD

    return dp[n][k]

