def oddness(p):
    return sum(abs(i - p[i]) for i in range(len(p)))

def count_permutations(n, k):
    count = 0
    for perm in permutations(range(1, n + 1)):
        if oddness(perm) == k:
            count += 1
    return count % (10**9 + 7)

