def count_permutations(n, k, memo):
    if (n, k) in memo:
        return memo[(n, k)]

    if n == 1:
        if k == 0:
            return 1
        else:
            return 0

    count = 0
    for i in range(1, n + 1):
        # Calculate the oddness contribution of the current element
        oddness_contribution = abs(i - 1)
        # Recursively count permutations for the remaining elements
        count += count_permutations(n - 1, k - oddness_contribution, memo)

    # Store the result in memoization
    memo[(n, k)] = count % (10**9 + 7)
    return count

