from collections import deque

def can_reach_points(points):
    N = len(points)
    if N > 40:
        return -1

    # Directions: L, R, D, U
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # BFS to find the shortest path
    def bfs(start, target):
        queue = deque([(start, '')])
        visited = set([start])

        while queue:
            current, path = queue.popleft()

            if current == target:
                return path

            for dx, dy in directions:
                new_x, new_y = current[0] + dx, current[1] + dy
                new_pos = (new_x, new_y)

                if new_pos not in visited:
                    visited.add(new_pos)
                    queue.append((new_pos, path + 'L' if dx == -1 else path + 'R' if dx == 1 else path + 'D' if dy == -1 else path + 'U'))

        return None

    # Try to find a path for each point
    for i, (x, y) in enumerate(points):
        path = bfs((0, 0), (x, y))
        if path is None:
            return -1

        # If a path is found, print the result
        print(i + 1)
        print(' '.join(map(str, [1] * i + [2] * (N - i - 1))))
        print(path)
        return

    return -1

