def sieve_of_eratosthenes(n):
    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (is_prime[p] == True):
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    prime_factors = []
    for p in range(2, n + 1):
        if is_prime[p]:
            prime_factors.append(p)
    return prime_factors

def count_valid_k(n):
    prime_factors = sieve_of_eratosthenes(n)
    count = 0
    for p in prime_factors:
        if p <= n:
            count += n // p
    return count

