def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def sum_of_gcds(N, K):
    MOD = 10**9 + 7
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: sum of gcds of sequences of length 1
    for j in range(1, K + 1):
        dp[1][j] = 1

    # Fill the dp table
    for i in range(2, N + 1):
        for j in range(1, K + 1):
            for k in range(1, K + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][k] * gcd(j, k)) % MOD

    # Sum the results for all sequences of length N
    result = sum(dp[N][j] for j in range(1, K + 1)) % MOD
    return result

