    MOD = 10**9 + 7
    # Initialize the DP table
    dp = [[[0] * (K + 1) for _ in range(K + 1)] for _ in range(N + 1)]

    # Base case: GCD of a single element is the element itself
    for i in range(1, K + 1):
        dp[1][i][i] = i

    # Fill the DP table
    for length in range(2, N + 1):
        for i in range(1, K + 1):
            for j in range(1, K + 1):
                for k in range(1, K + 1):
                    dp[length][i][j] = (dp[length][i][j] + dp[length - 1][i][k] * gcd(j, k)) % MOD

    # Sum up all possible sequences
    total_sum = 0
    for i in range(1, K + 1):
        for j in range(1, K + 1):
            for k in range(1, K + 1):
                total_sum = (total_sum + dp[N][i][j] * dp[N][j][k] * dp[N][k][i]) % MOD

    return total_sum

