def is_acyclic(graph):
    n = len(graph)
    visited = [False] * n
    parent = [-1] * n

    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                parent[neighbor] = node
                if dfs(neighbor):
                    return True
            elif parent[node] != neighbor:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i):
                return False
    return True

def min_days(graph):
    n = len(graph)
    visited = [False] * n
    max_depth = 0

    def dfs(node, depth):
        visited[node] = True
        nonlocal max_depth
        max_depth = max(max_depth, depth)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, depth + 1)

    for i in range(n):
        if not visited[i]:
            dfs(i, 1)
            max_depth = max(max_depth, 1)  # Each player plays one match per day

    return max_depth

