    # Create a graph to represent the matches
    graph = [[] for _ in range(N)]

    # Add edges to the graph
    for i in range(N):
        for opponent in opponents[i]:
            if opponent != i:
                graph[i].append(opponent)

    # Function to check if a graph is a collection of disjoint cycles
    def is_valid_graph():
        visited = [False] * N
        def dfs(node, parent):
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    if dfs(neighbor, node):
                        return True
                elif neighbor != parent:
                    return True
            return False

        for i in range(N):
            if not visited[i]:
                if dfs(i, -1):
                    return False
        return True

    # Check if the graph is a valid collection of disjoint cycles
    if not is_valid_graph():
        return -1

    # Calculate the number of days required
    # Each cycle of length 2 requires one day
    num_days = sum(1 for i in range(N) if len(graph[i]) == 1)

    return num_days

