def is_possible_to_schedule(N, schedules):
    # Create an adjacency list representation of the graph
    graph = defaultdict(list)
    for i in range(1, N + 1):
        for j in schedules[i - 1]:
            graph[i].append(j)

    # Function to perform topological sort
    def topological_sort():
        in_degree = [0] * (N + 1)
        queue = deque()

        # Calculate in-degrees
        for i in range(1, N + 1):
            for j in graph[i]:
                in_degree[j] += 1

        # Initialize queue with nodes having in-degree 0
        for i in range(1, N + 1):
            if in_degree[i] == 0:
                queue.append(i)

        # Perform topological sort
        topological_order = []
        while queue:
            node = queue.popleft()
            topological_order.append(node)
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return topological_order

    # Check for cycles using Kosaraju's algorithm
    def has_cycle():
        visited = [False] * (N + 1)
        stack = []
        for i in range(1, N + 1):
            if not visited[i]:
                dfs(i, visited, stack)

        # Reverse the graph
        reversed_graph = defaultdict(list)
        for i in range(1, N + 1):
            for j in graph[i]:
                reversed_graph[j].append(i)

        # Perform DFS on the reversed graph
        visited = [False] * (N + 1)
        scc_count = 0
        while stack:
            node = stack.pop()
            if not visited[node]:
                scc_count += 1
                dfs(node, visited, reversed_graph)

        return scc_count > 1

    # Perform topological sort if no cycle is found
    if not has_cycle():
        return len(topological_sort())
    else:
        return -1

