def count_numbers_with_k_non_zero_digits(N, K):
    count = 0
    if K == 1:
        # Count numbers from 1 to 9
        count = min(N, 9)
    elif K == 2:
        # Count numbers from 10 to 99
        count = min(N, 90) - 10 + 1
    elif K == 3:
        # Count numbers from 100 to 999
        count = min(N, 900) - 100 + 1
    else:
        # For K > 3, count numbers with exactly K digits
        # The first K-1 digits can be any digit from 1 to 9, and the last digit can be any digit from 1 to 9
        # The number of such numbers is 9^(K-1) * 9
        count = 9 ** (K - 1) * 9

    return count

