    # Initialize a hash map to store the count of each possible value of a + b - c - d
    count_map = defaultdict(int)

    # Iterate over all possible values of a, b, c, and d
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            for c in range(1, N + 1):
                for d in range(1, N + 1):
                    # Calculate the value of a + b - c - d
                    value = a + b - c - d
                    # Increment the count of this value in the hash map
                    count_map[value] += 1

    # Return the count of the value K
    return count_map[K]

