def count_quadruples(N, K):
    count = 0
    # Iterate over all possible values of a and b
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Calculate the required value for c + d
            required_sum = a + b - K
            # Check if required_sum is within the valid range
            if 2 * N - 2 <= required_sum <= 2 * N:
                # Count the number of valid pairs (c, d)
                count += min(required_sum, N) - max(required_sum, 1) + 1
    return count

