def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def can_generate_ratio(a, b, M_a, M_b):
    return a * M_b == b * M_a

def min_cost_to_generate_ratio(a, b, M_a, M_b, c):
    if not can_generate_ratio(a, b, M_a, M_b):
        return -1

    # Calculate the required amounts of A and B
    required_A = M_a * (a + b)
    required_B = M_b * (a + b)

    # Calculate the LCM of the required amounts
    lcm_AB = lcm(required_A, required_B)

    # Calculate the minimum cost
    min_cost = 0
    for i in range(N):
        if a[i] * M_b == b[i] * M_a:
            min_cost += c[i] * (lcm_AB // (a[i] * M_b))

    return min_cost

