    for a, b, c in packages:
        if a * M_b != b * M_a:
            print(-1)
            return

    # Initialize dp table
    dp = [[float('inf')] * (M_b + 1) for _ in range(M_a + 1)]
    dp[0][0] = 0

    # Fill the dp table
    for a, b, c in packages:
        for i in range(M_a, -1, -1):
            for j in range(M_b, -1, -1):
                if i >= a and j >= b:
                    dp[i][j] = min(dp[i][j], dp[i - a][j - b] + c)

    # Check if it's possible to achieve the desired ratio
    if dp[M_a][M_b] == float('inf'):
        print(-1)
    else:
        print(dp[M_a][M_b])

