def can_form_good_set(N, a):
    # Create the matrix A and the vector b
    A = []
    b = []

    # Iterate over each i from 1 to N
    for i in range(1, N + 1):
        row = [0] * N
        for j in range(1, N + 1):
            if j % i == 0:
                row[j - 1] = 1
        A.append(row)
        b.append(a[i - 1])

    # Convert A to a numpy array for easier manipulation
    import numpy as np
    A = np.array(A)
    b = np.array(b)

    # Solve the system of equations
    try:
        # Use numpy's linear algebra solver
        x = np.linalg.solve(A, b)
        # Check if the solution is in GF(2)
        if np.allclose(x, np.round(x)):
            return x.astype(int)
        else:
            return -1
    except np.linalg.LinAlgError:
        return -1

