    # Calculate the number of multiples of i within the range [1, N]
    def count_multiples(i):
        return N // i

    # Check if a good set of choices exists
    for i in range(1, N + 1):
        multiples = count_multiples(i)
        required_parity = a[i - 1] % 2
        if multiples % 2 != required_parity:
            return -1

    # If a good set of choices exists, print the result
    print(N)
    for i in range(1, N + 1):
        if count_multiples(i) % 2 == 1:
            print(i)

