def count_pairs(N, X, Y):
    if X == 1 and Y == N:
        # Simple path from 1 to N with an additional edge from 1 to N
        return (N - 1) * (N - 2) // 2
    elif X == 1:
        # Simple path from 1 to Y followed by an additional edge from Y to N
        return (Y - 1) * (Y - 2) // 2 + (N - Y)
    elif Y == N:
        # Simple path from X to N followed by an additional edge from X to 1
        return (N - X) * (N - X - 1) // 2 + (N - X)
    else:
        # Simple path from X to Y followed by an additional edge from Y to N and from X to 1
        return (Y - X) * (Y - X - 1) // 2 + (N - Y) + (N - X)

