import heapq

def dijkstra(graph, start):
    n = len(graph)
    distances = [float('inf')] * n
    distances[start] = 0
    pq = [(0, start)]

    while pq:
        current_distance, current_vertex = heapq.heappop(pq)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def count_pairs_with_distance(graph, start, end, k):
    n = len(graph)
    distances = dijkstra(graph, start)

    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if distances[i] == k and distances[j] == k and abs(i - j) == 1:
                count += 1
            elif distances[i] == k and distances[j] == k and abs(i - j) == 2:
                count += 1
            elif distances[i] == k and distances[j] == k and abs(i - j) == 3:
                count += 1
            elif distances[i] == k and distances[j] == k and abs(i - j) == 4:
                count += 1

    return count

