        self.n = n
        self.tree = [0] * (4 * n)

    def update(self, idx, val, l=0, r=None):
        if r is None:
            r = self.n - 1
        if l > r:
            return
        if l == r:
            self.tree[idx] = val
            return
        mid = (l + r) // 2
        self.update(2 * idx + 1, val, l, mid)
        self.update(2 * idx + 2, val, mid + 1, r)
        self.tree[idx] = self.tree[2 * idx + 1] + self.tree[2 * idx + 2]

    def query(self, l, r, idx=0, l_tree=0, r_tree=None):
        if r_tree is None:
            r_tree = self.n - 1
        if l > r_tree or r < l_tree:
            return 0
        if l <= l_tree and r >= r_tree:
            return self.tree[idx]
        mid = (l_tree + r_tree) // 2
        return self.query(l, r, 2 * idx + 1, l_tree, mid) + self.query(l, r, 2 * idx + 2, mid + 1, r_tree)

