                # Add walking edges
                if i > 0:
                    graph[i * W + j].append((i - 1) * W + j)
                if i < H - 1:
                    graph[i * W + j].append((i + 1) * W + j)
                if j > 0:
                    graph[i * W + j].append(i * W + j - 1)
                if j < W - 1:
                    graph[i * W + j].append(i * W + j + 1)

                # Add magic warp edges
