    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue for BFS with magic moves prioritized
    pq = []
    heapq.heappush(pq, (0, C_h, C_w))

    # Dictionary to store the minimum number of magic moves to reach each cell
    min_magic_moves = defaultdict(lambda: float('inf'))
    min_magic_moves[(C_h, C_w)] = 0

    while pq:
        current_magic_moves, x, y = heapq.heappop(pq)

        # If we reach the destination, return the number of magic moves
        if (x, y) == (D_h, D_w):
            return current_magic_moves

        # Explore all possible moves
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= H and 1 <= ny <= W and maze[nx][ny] == '.':
                # Walking move
                heapq.heappush(pq, (current_magic_moves + 1, nx, ny))

        # Explore magic moves
        for dx in range(-2, 3):
            for dy in range(-2, 3):
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if 1 <= nx <= H and 1 <= ny <= W and maze[nx][ny] == '.':
                    # Magic move
                    heapq.heappush(pq, (current_magic_moves + 2, nx, ny))

    # If no path is found, return -1
    return -1

