import sys

def dfs(node, parent, adj, dp):
    dp[node][node] = 1  # Each node is a connected component by itself
    for neighbor in adj[node]:
        if neighbor != parent:
            dfs(neighbor, node, adj, dp)
            for i in range(node + 1, neighbor + 1):
                for j in range(neighbor + 1, i + 1):
                    dp[i][j] = dp[i][j] + dp[i][neighbor] + dp[neighbor][j] - dp[i][neighbor] * dp[neighbor][j]
    return dp

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    edges = [(int(data[i]), int(data[i + 1])) for i in range(1, 2 * N, 2)]

    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Initialize DP table
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Compute the number of connected components for each subarray
    dfs(1, 0, adj, dp)

    # Calculate the sum of connected components for all subarrays
    total_sum = 0
    for i in range(1, N + 1):
        for j in range(i, N + 1):
            total_sum += dp[i][j]

    print(total_sum)

