from collections import defaultdict, deque

def topological_sort(graph):
    in_degree = [0] * (N + 1)
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue = deque([u for u in range(1, N + 1) if in_degree[u] == 0])
    topo_order = []

    while queue:
        u = queue.popleft()
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return topo_order

def max_score(graph, scores):
    for u in topo_order:
        for v, weight in graph[u]:
            scores[v] = max(scores[v], scores[u] + weight)

    return scores[N]

