from math import ceil

def floyd_warshall(graph):
    n = len(graph)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if graph[i][k] != float('inf') and graph[k][j] != float('inf'):
                    graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j])
    return graph

def min_fuel_tank_fills(n, m, l, roads, queries):
    # Initialize the graph
    graph = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        graph[i][i] = 0
    for A, B, C in roads:
        graph[A - 1][B - 1] = C
        graph[B - 1][A - 1] = C

    # Run Floyd-Warshall
    graph = floyd_warshall(graph)

    # Process each query
    results = []
    for s, t in queries:
        if graph[s - 1][t - 1] == float('inf'):
            results.append(-1)
        else:
            results.append(ceil(graph[s - 1][t - 1] / l))

    return results

