            if is_full:
                # If tank is full, we can travel to the next town without refueling
                new_dist = dist + length
                if new_dist < dp[v][0][1]:
                    dp[v][0][1] = new_dist
                    heapq.heappush(pq, (new_dist, v, 0, 1))
