                # If tank is not full, we can either travel to the next town or refuel
                new_dist = dist + length
                if new_dist < dp[v][fuel][0]:
                    dp[v][fuel][0] = new_dist
                    heapq.heappush(pq, (new_dist, v, fuel, 0))
                if fuel < L:
                    new_dist = dist + length
                    if new_dist < dp[v][fuel + 1][1]:
                        dp[v][fuel + 1][1] = new_dist
                        heapq.heappush(pq, (new_dist, v, fuel + 1, 1))

