def count_colorings(n, k, edges):
    # Build the adjacency list representation of the tree
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Depth array to store the color of each vertex at each depth level
    depth = [-1] * (n + 1)

    # Function to perform DFS and fill the depth array
    def dfs(node, parent, d):
        depth[node] = d
        for neighbor in graph[node]:
            if neighbor != parent:
                dfs(neighbor, node, d + 1)

    # Perform DFS to fill the depth array
    dfs(1, -1, 0)

    # DP table to store the number of ways to color the subtree rooted at vertex v
    # such that the color of vertex v is c and the depth of vertex v is d
    dp = [[[0] * k for _ in range(n + 1)] for _ in range(n + 1)]

    # Base case: there's one way to color a vertex with a specific color at depth 0
    for c in range(k):
        dp[1][0][c] = 1

    # Fill the DP table
    for d in range(1, n):
        for v in range(1, n + 1):
            if depth[v] == d:
                for c in range(k):
                    for neighbor in graph[v]:
                        if depth[neighbor] == d + 2:
                            for nc in range(k):
                                if nc != c:
                                    dp[v][d][c] += dp[neighbor][d + 2][nc]
                                    dp[v][d][c] %= 1000000007

    # Sum up all valid colorings for the root vertex
    result = 0
    for c in range(k):
        result += dp[1][0][c]
        result %= 1000000007

    return result

