def count_ways(n: int, k: int, edges: List[List[int]]) -> int:
    MOD = 10**9 + 7

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    # Calculate distances from each vertex to all other vertices
    distances = [bfs(graph, i) for i in range(n)]

    # Initialize DP table
    dp = [[0] * (1 << k) for _ in range(n)]
    dp[0][1] = 1  # Start with the first vertex colored with the first color

    # Fill the DP table
    for i in range(1, n):
        for mask in range(1 << k):
            for j in range(k):
                if mask & (1 << j):
                    for neighbor in graph[i]:
                        if distances[i][neighbor] <= 2:
                            continue
                        new_mask = mask ^ (1 << j)
                        dp[i][mask] += dp[neighbor][new_mask]
                        dp[i][mask] %= MOD

    # Sum up all valid colorings for the root vertex
    result = sum(dp[0]) % MOD

    return result

