def count_colorings(graph: defaultdict, distances: List[int], K: int) -> int:
    n = len(graph)
    MOD = 10**9 + 7

    # Initialize DP table
    dp = [0] * (1 << n)
    dp[0] = 1  # Base case: no vertices colored

    for vertex in range(n):
        for color in range(K):
            # Check if the vertex is not colored
            if (1 << vertex) & dp[vertex] == 0:
                # Check if the vertex is not at distance 2 from any colored vertex
                for neighbor in graph[vertex]:
                    if distances[neighbor] <= 2 and (1 << neighbor) & dp[vertex] != 0:
                        break
                else:
                    # Update the DP table
                    for prev_color in range(K):
                        if (1 << prev_color) & dp[vertex] == 0:
                            dp[(1 << vertex) | (1 << prev_color)] = (dp[(1 << vertex) | (1 << prev_color)] + dp[vertex]) % MOD

    return dp[(1 << n) - 1]

