def count_colorings(graph, distances, K):
    n = len(graph)
    MOD = 10**9 + 7

    # Initialize DP table
    dp = [0] * (1 << n)
    dp[0] = 1  # Base case: all vertices uncolored

    # Iterate over each vertex
    for u in range(n):
        # Calculate the bitmask for the current vertex
        mask = (1 << u)

        # Iterate over all possible colorings of the neighbors
        for v in graph[u]:
            # Calculate the bitmask for the neighbor
            neighbor_mask = (1 << v)

            # Iterate over all possible colorings of the vertices at distance 2
            for w in graph[v]:
                if distances[u][w] == 2:
                    # Calculate the bitmask for the vertex at distance 2
                    distance_2_mask = (1 << w)

                    # Update the DP table
                    for k in range(1 << n):
                        if k & mask and k & neighbor_mask and k & distance_2_mask == 0:
                            dp[k | mask] = (dp[k | mask] + dp[k]) % MOD

    # Sum up all valid colorings
    result = sum(dp) % MOD
    return result

