def is_consistent(assignment, s):
    N = len(assignment)
    for i in range(N):
        if s[i] == 'o':
            if assignment[i] != assignment[(i + 1) % N] or assignment[i] != assignment[(i - 1) % N]:
                return False
        else:
            if assignment[i] == assignment[(i + 1) % N] or assignment[i] == assignment[(i - 1) % N]:
                return False
    return True

def backtrack(assignment, s, index):
    N = len(assignment)
    if index == N:
        if is_consistent(assignment, s):
            print(''.join(assignment))
            return True
        return False

    for species in ['S', 'W']:
        assignment[index] = species
        if backtrack(assignment, s, index + 1):
            return True
        assignment[index] = ' '  # Backtrack

    return False

