    duplicates = []
    for i in range(1, len(A)):
        if A[i] == A[i - 1]:
            duplicates.append(A[i])

    # Check if we can reorder B to avoid duplicates
    for duplicate in duplicates:
        found = False
        for j in range(len(B)):
            if B[j] != duplicate:
                found = True
                B[j], B[-1] = B[-1], B[j]
                break
        if not found:
            return False

    return True

