def tarjan_scc(graph):
    n = len(graph)
    visited = [False] * n
    low = [0] * n
    disc = [0] * n
    stack = []
    scc = []
    time = 0

    def dfs(node, parent):
        nonlocal time
        visited[node] = True
        disc[node] = low[node] = time
        time += 1
        stack.append(node)

        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, node)
                low[node] = min(low[node], low[neighbor])
            elif neighbor != parent:
                low[node] = min(low[node], disc[neighbor])

        if low[node] == disc[node]:
            scc_component = []
            while stack and stack[-1] != node:
                scc_component.append(stack.pop())
            scc_component.append(stack.pop())
            scc.append(scc_component)

    for node in range(n):
        if not visited[node]:
            dfs(node, -1)

    return scc

def can_place_signposts(graph, n):
    sccs = tarjan_scc(graph)
    if len(sccs) != 1:
        return "No"

    # Check if the SCC contains all rooms except Room 1
    scc = sccs[0]
    if len(scc) != n - 1:
        return "No"

    # Place signposts such that each room points to any room in the same SCC
    signposts = [0] * n
    for room in scc:
        signposts[room] = room

    return "Yes" + "\n" + "\n".join(map(str, signposts[1:]))

