def bfs(graph, start):
    queue = deque([(start, 0)])
    visited = set([start])
    min_path = float('inf')
    min_room = None

    while queue:
        room, path = queue.popleft()
        if path < min_path:
            min_path = path
            min_room = room

        for neighbor in graph[room]:
