    graph = defaultdict(list)

    # Build the graph
    for A, B in edges:
        graph[A].append(B)
        graph[B].append(A)

    # Find the shortest path to Room 1 for each room except Room 1
    signposts = []
    for room in range(2, N + 1):
        min_room = bfs(graph, room)
        signposts.append(min_room)

    # Check if the signposts satisfy the condition
    for room, signpost in enumerate(signposts, start=2):
        if bfs(graph, signpost) != 1:
            return "No"

    return "Yes", signposts

