            return False
        if grid[x-1][y] == '#' or grid[x][y-1] == '#':
            return False
        return is_valid_path(x+1, y) or is_valid_path(x, y+1)

    # Check if there is a path from (1, 1) to (H, W)
    if not is_valid_path(1, 1):
        return -1

    # Count the number of white squares on the path
