import heapq

def sum_of_digits(n):
    return sum(int(digit) for digit in str(n))

def find_snuke_numbers(K):
    # Priority queue to store (sum_of_digits, number)
    pq = []

    # Start with the smallest number
    for n in range(1, 10**15 + 1):
        # Calculate the sum of digits
        s = sum_of_digits(n)

        # Check if n is a Snuke number
        is_snuke = True
        for m in range(n + 1, 10**15 + 1):
            if s > sum_of_digits(m):
                is_snuke = False
                break

        # If n is a Snuke number, add it to the priority queue
        if is_snuke:
            heapq.heappush(pq, (s, n))

        # If we have found K Snuke numbers, stop
        if len(pq) == K:
            break

    # Extract the K smallest Snuke numbers
    return [n for _, n in heapq.nsmallest(K, pq)]

