    color_index = 0
    for i in range(H):
        for j in range(W):
            # Assign the current color to the current square
            grid[i][j] = color_index + 1

            # Decrease the count of the current color
            a[color_index] -= 1

            # If the count of the current color is zero, move to the next color
            if a[color_index] == 0:
                color_index += 1

    # Print the grid
    for row in grid:
        print(' '.join(map(str, row)))

